const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

struct Node;

fn intent_label(intent: &Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

fn error(message: &str) -> ResponseResult {
    ResponseResult::Error(LlmError {
        message: message.to_string(),
    })
}

/// Percent-encode everything outside the RFC 3986 unreserved set, so the
/// input text cannot alter the URL's structure (no extra parameters, no host
/// or path change).
fn encode_query(input: &str) -> String {
    let mut out = String::with_capacity(input.len() * 3);
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

/// Fetch the enrichment record for the question. The record is deliberately
/// not folded into the prompt or the answer, so the node's output is unchanged.
/// `fetch` reports transport failure as a value, so a failed enrichment cannot
/// fail the run.
fn enrich(question: &str) {
    let url = format!("{}{}", ENRICH_BASE, encode_query(question));
    let _ = http_client::fetch(&url);
}

